import{describe,it,expect}from"vitest";function checkAnswer(e,t){return t===quizQuestions[e].answer}function calculateScore(e){return e.reduce((e,{questionIndex:t,selected:c})=>e+(checkAnswer(t,c)?1:0),0)}function createFreshQuizState(){return{currentQuestionIndex:0,score:0,locked:!1}}describe("Quiz answer matching",()=>{it("checkAnswer returns true for correct answer",()=>{expect(checkAnswer(0,"Bihar")).toBe(!0),expect(checkAnswer(1,"Goa")).toBe(!0),expect(checkAnswer(7,"Andhra Pradesh")).toBe(!0)}),it("checkAnswer returns false for incorrect answer",()=>{expect(checkAnswer(0,"Rajasthan")).toBe(!1),expect(checkAnswer(1,"Kerala")).toBe(!1),expect(checkAnswer(7,"Telangana")).toBe(!1)}),it("checkAnswer is case-sensitive (matches exact string)",()=>{expect(checkAnswer(0,"bihar")).toBe(!1),expect(checkAnswer(0,"BIHAR")).toBe(!1)})}),describe("Quiz score calculation",()=>{it("perfect score returns 8",()=>{const e=quizQuestions.map((e,t)=>({questionIndex:t,selected:e.answer}));expect(calculateScore(e)).toBe(8)}),it("zero correct returns 0",()=>{const e=quizQuestions.map((e,t)=>({questionIndex:t,selected:"Nonexistent Option"}));expect(calculateScore(e)).toBe(0)}),it("partial correct returns correct count",()=>{const e=quizQuestions.map((e,t)=>({questionIndex:t,selected:e.options[0]})),t=quizQuestions.filter(e=>e.answer===e.options[0]).length;expect(calculateScore(e)).toBe(t)}),it("score is always between 0 and 8",()=>{for(let e=0;e<=8;e++){const t=calculateScore(quizQuestions.map((t,c)=>({questionIndex:c,selected:c<e?t.answer:"Wrong Answer"})));expect(t).toBeGreaterThanOrEqual(0),expect(t).toBeLessThanOrEqual(8)}})}),describe("Quiz state management",()=>{it("fresh quiz state has index 0, score 0, unlocked",()=>{const e=createFreshQuizState();expect(e.currentQuestionIndex).toBe(0),expect(e.score).toBe(0),expect(e.locked).toBe(!1)}),it("score increments only on correct answer",()=>{let e=0;const t=quizQuestions[0].answer,c=quizQuestions[0].options.find(e=>e!==t);t===c&&e++,expect(e).toBe(0),e++,expect(e).toBe(1),e=3,expect(e).toBe(3)})}),describe("Quiz edge cases",()=>{it("every question answer is reachable via options",()=>{quizQuestions.forEach(e=>{expect(e.options).toContain(e.answer)})}),it("no question has an empty answer",()=>{quizQuestions.forEach(e=>{expect(e.answer.trim().length).toBeGreaterThan(0)})})});